import { test, expect, type Page } from '@playwright/test';
import fs from 'fs';

// Load real authenticated Supabase sessions generated by scripts/seed_paper_test_users.js
const authDataRaw = fs.readFileSync('tests/.auth-sessions.json', 'utf-8');
const authData = JSON.parse(authDataRaw) as {
  storageKey: string;
  password: string;
  accounts: Record<string, { profile: any; session: any }>;
};

type AccountKey =
  | 'admin'
  | 'coach'
  | 'facilitator'
  | 'student_verified'
  | 'faculty_verified'
  | 'staff_verified'
  | 'student_pending'
  | 'faculty_pending'
  | 'staff_pending';

/**
 * Injects a real Supabase Auth session (never dev impersonation) and enforces Light Mode.
 */
async function configureSessionAndTheme(page: Page, accountKey: AccountKey | null) {
  const storageKey = authData.storageKey;
  const rawSession = accountKey ? authData.accounts[accountKey]?.session : null;
  const futureExpiresAt = Math.floor(Date.now() / 1000) + 86400;
  const sessionObj = rawSession
    ? {
        ...rawSession,
        expires_in: 86400,
        expires_at: futureExpiresAt,
      }
    : null;

  if (sessionObj) {
    // Intercept auth refresh/user endpoints so parallel Playwright workers never invalidate the shared refresh_token
    await page.route('**/auth/v1/**', async (route) => {
      const url = route.request().url();
      if (url.includes('/user')) {
        await route.fulfill({
          status: 200,
          contentType: 'application/json',
          body: JSON.stringify(sessionObj.user),
        });
      } else if (url.includes('/token') || url.includes('/session')) {
        await route.fulfill({
          status: 200,
          contentType: 'application/json',
          body: JSON.stringify(sessionObj),
        });
      } else {
        await route.continue();
      }
    });
  }

  await page.addInitScript(
    ({ key, session }) => {
      try {
        // 1. Set real Supabase Auth session FIRST
        if (session) {
          localStorage.setItem(key, JSON.stringify(session));
        } else {
          localStorage.removeItem(key);
        }

        // 2. Always remove dev impersonation so the top IMPERSONATING banner never renders
        localStorage.removeItem('psu_dev_impersonated_persona');

        // 3. Force clean Light Mode for academic paper documentation
        localStorage.setItem('psu-sportstrack-theme', 'light');
        localStorage.setItem('vite-ui-theme', 'light');
        localStorage.setItem('theme', 'light');
        document.documentElement?.classList?.remove('dark');
        document.documentElement?.classList?.add('light');
      } catch {
        // Ignore early DOM errors
      }
    },
    { key: storageKey, session: sessionObj }
  );
}

/**
 * Waits until all lazy chunks, network requests, PageSkeletons, and SkeletonCards finish loading.
 */
async function waitForContentReady(page: Page, extraDelayMs = 800) {
  await page.waitForLoadState('domcontentloaded');
  await page.waitForLoadState('networkidle', { timeout: 6000 }).catch(() => {});

  // Force Light Mode class on documentElement and hide any transient toast popups
  await page.evaluate(() => {
    document.documentElement.classList.remove('dark');
    document.documentElement.classList.add('light');
  });

  // Poll until zero skeleton blocks (.animate-shimmer from PageSkeleton/SkeletonCard) remain visible
  await page
    .waitForFunction(
      () => {
        const candidates = Array.from(
          document.querySelectorAll('.animate-shimmer, [data-slot="skeleton"]')
        );
        const visibleSkeletons = candidates.filter((el) => {
          const rect = el.getBoundingClientRect();
          const style = window.getComputedStyle(el);
          if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') {
            return false;
          }
          return rect.width > 20 && rect.height > 10;
        });
        return visibleSkeletons.length === 0;
      },
      { timeout: 15000 }
    )
    .catch(() => {});

  // Hide any sonner toast notifications so they don't cover corners in documentation
  await page.addStyleTag({
    content: `[data-sonner-toaster], .toaster { display: none !important; }`,
  }).catch(() => {});

  await page.waitForTimeout(extraDelayMs);
}

/**
 * Scrolls smoothly to either a specific text/selector or a pixel offset.
 */
async function scrollPageTo(
  page: Page,
  target: { text?: string | RegExp; selector?: string; yOffset?: number; fallbackY?: number }
) {
  if (target.text) {
    const loc = page.getByText(target.text).first();
    if (await loc.isVisible().catch(() => false)) {
      await loc.evaluate((el) => {
        const y = el.getBoundingClientRect().top + window.scrollY - 76;
        window.scrollTo({ top: Math.max(0, y), behavior: 'instant' });
      });
      await page.waitForTimeout(400);
      return;
    }
  }
  if (target.selector) {
    const loc = page.locator(target.selector).first();
    if (await loc.isVisible().catch(() => false)) {
      await loc.evaluate((el) => {
        const y = el.getBoundingClientRect().top + window.scrollY - 76;
        window.scrollTo({ top: Math.max(0, y), behavior: 'instant' });
      });
      await page.waitForTimeout(400);
      return;
    }
  }
  const y = target.yOffset ?? target.fallbackY ?? 520;
  await page.evaluate((scrollY) => {
    window.scrollTo({ top: scrollY, behavior: 'instant' });
  }, y);
  await page.waitForTimeout(400);
}

